package io.zem.ibox;
import android.content.*;import android.net.Uri;import android.text.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
final class PhoneLibraryScreen {
    final MainActivity a;private String query="";private int kind,order;private boolean selecting;private final Set<String> selected=new HashSet<>();private JSONArray visible=new JSONArray();private Button selection,share,play;private TextView resultStatus;
    PhoneLibraryScreen(MainActivity a){this.a=a;}
    private static String kind(JSONObject item){String origin=item.optString("origin");return (origin.equals("live camera")||origin.equals("RTSP live"))?"Лайв":origin.equals("import")?"Добавлено":origin.equals("player frame")?"Кадр":origin.equals("clip")?"Фрагмент":"Оригинал";}
    private static String date(JSONObject item){String at=item.optString("recordedAt");return at.isEmpty()?new java.text.SimpleDateFormat("dd.MM.yyyy HH:mm:ss",Locale.ROOT).format(new Date(item.optLong("at"))):at;}
    private static String day(JSONObject item){String value=date(item);return value.length()>=10?value.substring(0,10):"Дата неизвестна";}
    void page(){a.refreshLocalFiles();JSONArray all=Library.all(a);a.localCount=all.length();LinearLayout header=a.column();header.addView(Ui.heading(a,"На телефоне","Сохранено файлов: "+all.length()));header.addView(a.text("Папка: "+StorageLocation.label(a),12,Ui.MUTED));EditText search=a.input("Найти по имени или дате",query);search.setSingleLine();search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){query=s.toString();render();}public void afterTextChanged(Editable e){}});header.addView(search);
        Spinner types=spinner(new String[]{"Все файлы","Оригиналы регистратора","Записи лайва","Кадры и фото","Добавленные файлы"},kind,value->{kind=value;render();});Spinner sort=spinner(new String[]{"Сначала новые","Сначала старые","По имени","Сначала большие"},order,value->{order=value;render();});LinearLayout tools=a.responsiveRow();Button filters=a.button("Фильтры и сортировка",false);filters.setOnClickListener(v->{LinearLayout content=a.column();content.setPadding(a.dp(16),a.dp(12),a.dp(16),a.dp(12));for(Spinner control:new Spinner[]{types,sort}){if(control.getParent() instanceof ViewGroup parent)parent.removeView(control);content.addView(control);}new android.app.AlertDialog.Builder(a).setTitle("Файлы на телефоне").setView(Widgets.dialogBody(a,content)).setPositiveButton("Готово",null).show();});tools.addView(filters,a.pairParams(tools));
        selection=a.button("Выбрать файлы",false);selection.setOnClickListener(v->{selecting=!selecting;if(!selecting)selected.clear();render();});tools.addView(selection,a.pairParams(tools));header.addView(tools);resultStatus=a.text("",12,Ui.MUTED);header.addView(resultStatus);Button importFiles=a.button("Добавить существующие файлы",false);importFiles.setOnClickListener(v->a.importFiles());
        a.localList=new ListView(a);a.localList.setDivider(new android.graphics.drawable.ColorDrawable(android.graphics.Color.TRANSPARENT));a.localList.setDividerHeight(a.dp(10));a.localList.addHeaderView(header,null,false);LinearLayout footer=a.column();footer.addView(importFiles);play=a.button("Смотреть видео подряд",false);play.setOnClickListener(v->a.openLocalQueue(chosen(),null));footer.addView(play);share=a.button("Поделиться выбранными",false);share.setOnClickListener(v->share());footer.addView(share);Button folder=a.button("Открыть папку записей",false);Ui.leading(folder,"folder");folder.setOnClickListener(v->a.openRecordingsFolder());footer.addView(folder);a.localList.addFooterView(footer,null,false);a.body.addView(a.localList,new LinearLayout.LayoutParams(-1,-1));render();
    }
    private Spinner spinner(String[] labels,int value,java.util.function.IntConsumer selected){Spinner spinner=new Spinner(a);spinner.setMinimumHeight(a.dp(48));spinner.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,labels));spinner.setSelection(value);spinner.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> parent,View v,int position,long id){selected.accept(position);}public void onNothingSelected(AdapterView<?> parent){}});return spinner;}
    private void render(){if(a.localList==null||a.tab!=2)return;List<JSONObject> items=new ArrayList<>();JSONArray all=Library.all(a);String q=query.toLowerCase(Locale.ROOT);for(int i=0;i<all.length();i++){JSONObject item=all.optJSONObject(i);if(!(item.optString("name")+" "+date(item)).toLowerCase(Locale.ROOT).contains(q))continue;String type=kind(item);if(kind==1&&!type.equals("Оригинал")||kind==2&&!type.equals("Лайв")||kind==3&&!item.optString("mime").startsWith("image/")||kind==4&&!type.equals("Добавлено"))continue;items.add(item);}
        items.sort((x,y)->order==2?x.optString("name").compareToIgnoreCase(y.optString("name")):order==3?Long.compare(y.optLong("size"),x.optLong("size")):order==1?Long.compare(x.optLong("at"),y.optLong("at")):Long.compare(y.optLong("at"),x.optLong("at")));visible=new JSONArray(items);Set<String> available=new HashSet<>();for(int i=0;i<all.length();i++)available.add(all.optJSONObject(i).optString("uri"));selected.retainAll(available);if(resultStatus!=null)resultStatus.setText(items.isEmpty()?(all.length()==0?"Сохраните видео с камеры или добавьте существующие файлы":"Ничего не найдено. Измените поиск или фильтры"):"Найдено файлов: "+items.size());selection.setText(selecting?"Готово · "+selected.size():"Выбрать");share.setVisibility(selecting?View.VISIBLE:View.GONE);share.setEnabled(!selected.isEmpty());play.setText(selecting?"Смотреть выбранные видео":"Смотреть видео подряд");boolean hasVideo=false;JSONArray playback=chosen();for(int i=0;i<playback.length();i++)hasVideo|=playback.optJSONObject(i).optString("mime").startsWith("video/");play.setEnabled(hasVideo);
        a.localList.setAdapter(a.new Rows(items.size(),i->{JSONObject item=items.get(i);return (selected.contains(item.optString("uri"))?"Выбрано · ":"")+item.optString("name")+"\n"+date(item)+" · "+kind(item)+" · "+TransferService.bytes(item.optLong("size"));},i->activate(items.get(i)),i->actions(items.get(i)),i->MediaThumbnails.Source.local(items.get(i))).sections(i->i==0||!day(items.get(i)).equals(day(items.get(i-1)))?day(items.get(i)):""));
    }
    private JSONArray chosen(){if(!selecting)return visible;JSONArray out=new JSONArray();JSONArray library=Library.all(a);for(int i=0;i<library.length();i++){JSONObject item=library.optJSONObject(i);if(selected.contains(item.optString("uri")))out.put(item);}return out;}
    private void activate(JSONObject item){if(selecting){String uri=item.optString("uri");if(!selected.add(uri))selected.remove(uri);render();}else if(item.optString("mime").startsWith("video/"))a.openLocalQueue(visible,item.optString("uri"));else a.openLocal(Uri.parse(item.optString("uri")),item.optString("mime"));}
    void actions(JSONObject item){boolean video=item.optString("mime").startsWith("video/");new android.app.AlertDialog.Builder(a).setTitle(item.optString("name")).setItems(video?new String[]{"Открыть в…","Внутренний плеер","Открыть через VLC","Поделиться"}:new String[]{"Открыть в…","Поделиться"},(d,n)->{Uri uri=Uri.parse(item.optString("uri"));if(n==0)a.openLocal(uri,item.optString("mime"));else if(video&&n==1)a.openLocalQueue(visible,uri.toString());else if(video&&n==2)a.openLocalIn(uri,item.optString("mime"),true);else a.share(uri,item.optString("mime"));}).show();}
    private void share(){JSONArray items=chosen();ArrayList<Uri> uris=new ArrayList<>();for(int i=0;i<items.length();i++)uris.add(Uri.parse(items.optJSONObject(i).optString("uri")));if(uris.isEmpty())return;Intent send=new Intent(Intent.ACTION_SEND_MULTIPLE).setType("*/*").putParcelableArrayListExtra(Intent.EXTRA_STREAM,uris).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);ClipData clip=ClipData.newRawUri("Записи",uris.get(0));for(int i=1;i<uris.size();i++)clip.addItem(new ClipData.Item(uris.get(i)));send.setClipData(clip);try{a.startActivity(Intent.createChooser(send,"Поделиться записями"));}catch(ActivityNotFoundException e){a.toast("Нет приложения для отправки файлов");}}
}
